import{_ as e,c as i,o as a,ag as t}from"./chunks/framework.BgId8OS5.js";const u=JSON.parse('{"title":"12.4 Performance","description":"","frontmatter":{},"headers":[],"relativePath":"bonnes-pratiques/performance.md","filePath":"bonnes-pratiques/performance.md"}'),n={name:"bonnes-pratiques/performance.md"};function l(r,s,p,o,d,h){return a(),i("div",null,s[0]||(s[0]=[t('<h1 id="_12-4-performance" tabindex="-1">12.4 Performance <a class="header-anchor" href="#_12-4-performance" aria-label="Permalink to &quot;12.4 Performance&quot;">​</a></h1><p>Un site performant se charge rapidement et reste fluide, même sur des connexions lentes ou des appareils peu puissants. Voici comment optimiser la performance de vos pages web :</p><h2 id="optimiser-la-taille-des-images" tabindex="-1">Optimiser la taille des images <a class="header-anchor" href="#optimiser-la-taille-des-images" aria-label="Permalink to &quot;Optimiser la taille des images&quot;">​</a></h2><p>Les images trop lourdes ralentissent le chargement. Compressez-les et choisissez le format le plus adapté (JPEG pour les photos, PNG pour les images avec transparence, SVG pour les icônes).</p><blockquote><p><strong>Astuce :</strong> Utilisez des outils comme TinyPNG ou Squoosh pour réduire la taille des images sans perte visible de qualité.</p></blockquote><h2 id="charger-les-scripts-efficacement" tabindex="-1">Charger les scripts efficacement <a class="header-anchor" href="#charger-les-scripts-efficacement" aria-label="Permalink to &quot;Charger les scripts efficacement&quot;">​</a></h2><p>Placez les balises <code>&lt;script&gt;</code> juste avant la fermeture de <code>&lt;/body&gt;</code> ou utilisez l’attribut <code>defer</code> pour que le chargement du JavaScript ne bloque pas l’affichage de la page.</p><h3 id="differences-entre-defer-et-async" tabindex="-1">Différences entre <code>defer</code> et <code>async</code> <a class="header-anchor" href="#differences-entre-defer-et-async" aria-label="Permalink to &quot;Différences entre `defer` et `async`&quot;">​</a></h3><ul><li><p><strong><code>defer</code></strong> :</p><ul><li>Le script est téléchargé en parallèle du HTML, mais il n’est exécuté qu’une fois que tout le document HTML est entièrement analysé (juste avant l’événement <code>DOMContentLoaded</code>).</li><li>Les scripts avec <code>defer</code> sont exécutés dans l’ordre où ils apparaissent dans le code.</li><li>Idéal pour les scripts qui dépendent du DOM complet ou d’autres scripts.</li></ul><p><strong>Exemple :</strong></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;autre.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Ici, <code>main.js</code> sera toujours exécuté avant <code>autre.js</code>, même si le second se télécharge plus vite.</p></li><li><p><strong><code>async</code></strong> :</p><ul><li>Le script est téléchargé en parallèle du HTML et exécuté dès qu’il est prêt, sans attendre la fin de l’analyse du HTML.</li><li>L’ordre d’exécution n’est pas garanti si plusieurs scripts sont en <code>async</code>.</li><li>À utiliser pour les scripts indépendants (ex : analytics, widgets externes).</li></ul><p><strong>Exemple :</strong></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;analytics.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;widget.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Ici, <code>analytics.js</code> et <code>widget.js</code> seront exécutés dès qu’ils sont chargés, dans un ordre imprévisible.</p></li></ul><blockquote><p><strong>Astuce :</strong> N’utilisez pas <code>async</code> pour des scripts qui dépendent les uns des autres ou du DOM complet.</p></blockquote><h2 id="limiter-le-nombre-de-requetes-http" tabindex="-1">Limiter le nombre de requêtes HTTP <a class="header-anchor" href="#limiter-le-nombre-de-requetes-http" aria-label="Permalink to &quot;Limiter le nombre de requêtes HTTP&quot;">​</a></h2><p>Chaque fichier CSS ou JS externe ajoute une requête au serveur. Regroupez vos fichiers quand c’est possible pour réduire leur nombre.</p><blockquote><p><strong>Astuce :</strong> Utilisez des outils de build (Webpack, Parcel, etc.) pour fusionner et minifier vos fichiers.</p></blockquote><h2 id="privilegier-les-animations-css" tabindex="-1">Privilégier les animations CSS <a class="header-anchor" href="#privilegier-les-animations-css" aria-label="Permalink to &quot;Privilégier les animations CSS&quot;">​</a></h2><p>Les animations CSS sont généralement plus performantes que celles faites en JavaScript, car elles sont optimisées par le navigateur.</p><blockquote><p><strong>Astuce :</strong> Préférez animer les propriétés <code>transform</code> et <code>opacity</code> pour des transitions fluides.</p></blockquote><h2 id="lazy-loading-des-ressources-non-critiques" tabindex="-1">Lazy loading des ressources non critiques <a class="header-anchor" href="#lazy-loading-des-ressources-non-critiques" aria-label="Permalink to &quot;Lazy loading des ressources non critiques&quot;">​</a></h2><p>Chargez les images ou contenus non essentiels uniquement quand ils deviennent visibles à l’écran (lazy loading). Cela accélère le chargement initial de la page.</p><p><strong>Exemple :</strong></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;photo.jpg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loading</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lazy&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Description de la photo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><blockquote><p><strong>Astuce :</strong> Le lazy loading est pris en charge nativement par la plupart des navigateurs modernes avec l’attribut <code>loading=&quot;lazy&quot;</code>.</p></blockquote>',21)]))}const k=e(n,[["render",l]]);export{u as __pageData,k as default};
